function labelForCharacterInitiativeValue(ruleset, val) {
  if (ruleset.baseRulesetId == "classic") {
    if (val === true) {
      return "Has initiative";
    } else if (val === false) {
      return "No initiative";
    }
  } else {
    if (val === true) {
      return "In control";
    } else if (val === false) {
      return "In a bad spot";
    }
  }
  return "Out of combat";
}
function labelForCharacterInitiative(ruleset) {
  return ruleset.baseRulesetId == "classic" ? "initiative" : "position";
}
function labelForCharacterCallsign(ruleset) {
  if (ruleset.baseRulesetId == "starforged") {
    if (ruleset.rulesPackageIds.includes("sundered_isles")) {
      return "Moniker";
    } else {
      return "Callsign";
    }
  } else {
    return "Alias";
  }
}

