var import_obsidian49 = require("obsidian");
async function insertComment(plugin, editor) {
  const comment = await PromptModal.prompt(plugin.app, "Enter your comment");
  appendNodesToMoveOrMechanicsBlock(editor, createDetailsNode(comment));
}
async function rollDice(plugin, editor, view) {
  const localSettings = view.file && plugin.localSettings.forCampaign(view.file);
  const roll = await CustomSuggestModal.selectWithUserEntry(
    plugin.app,
    localSettings?.recentRolls ?? [],
    ({ expression }) => expression,
    (input, el) => {
      try {
        const parsed2 = new DiceExprGroup([parseDiceExpression(input)]);
        el.textContent = parsed2.exprs[0].toString();
      } catch (error43) {
        el.textContent = `Invalid expression: ${error43}`;
      }
    },
    () => {
    },
    "Enter your dice roll (e.g., 2d6+3)",
    (input) => ({
      expression: input
    })
  );
  const roller = plugin.settings.graphicalActionDice ? new GraphicalDiceRoller(plugin) : PlainDiceRoller.INSTANCE;
  let parsed;
  try {
    parsed = new DiceExprGroup([parseDiceExpression(roll.value.expression)]);
  } catch (error43) {
    console.error("Failed to parse dice expression:", error43);
    new import_obsidian49.Notice("Invalid dice expression. Please use a format like '2d6+3'.");
    return;
  }
  if (localSettings) {
    localSettings.addRecentRoll(parsed.exprs[0].toString());
  }
  const dice = parsed.flattenDiceToGroup();
  const rolls = await roller.rollAsync(dice);
  const evaledExpr = parsed.applyValues(rolls).exprs[0];
  appendNodesToMoveOrMechanicsBlock(
    editor,
    createDiceExpressionNode({ evaledExpr })
  );
}

