// src/tracks/commands.ts
async function advanceProgressTrack(plugin, editor, view) {
  const actionContext = await determineCharacterActionContext(plugin, view);
  const progressContext = new ProgressContext(plugin, actionContext);
  const trackContext = await selectProgressTrack(
    progressContext,
    plugin,
    ({ track }) => !track.complete && track.ticksRemaining > 0
  );
  const steps = await CustomSuggestModal.select(
    plugin.app,
    Array(trackContext.track.stepsRemaining).fill(0).map((_3, i7) => i7 + 1),
    (num) => num.toString(),
    void 0,
    "Select number of times to advance the progress track."
  );
  await trackContext.process((trackAdapter) => trackAdapter.advanced(steps));
  appendNodesToMoveOrMechanicsBlock(
    editor,
    createProgressNode(
      stripMarkdown(plugin, trackContext.name),
      trackContext,
      steps
    )
  );
}
async function createProgressTrack(plugin, editor) {
  const trackInput = await ProgressTrackCreateModal.show(plugin);
  const track = ProgressTrackFileAdapter.newFromTrack(trackInput);
  const file2 = await createNewIronVaultEntityFile(
    plugin.app,
    trackInput.targetFolder,
    trackInput.fileName,
    "progress" /* ProgressTrack */,
    {
      ...track.raw,
      "track-type": trackInput.trackType
    },
    plugin.settings.progressTrackTemplateFile,
    `
\`\`\`${BLOCK_TYPE__TRACK}
\`\`\`

`
  );
  appendNodesToMoveOrMechanicsBlock(
    editor,
    createTrackCreationNode(stripMarkdown(plugin, trackInput.name), file2.path),
    ...plugin.settings.inlineOnCreation ? [createDetailsNode(`![[${file2.path}|iv-embed]]`)] : []
  );
}
async function markTrackCompleted(plugin, editor, view) {
  const actionContext = await determineCharacterActionContext(plugin, view);
  const progressContext = new ProgressContext(plugin, actionContext);
  const trackContext = await selectProgressTrack(
    progressContext,
    plugin,
    ({ trackType, track }) => trackType !== "Legacy" && !track.complete
  );
  await trackContext.process((trackAdapter) => trackAdapter.completed());
  appendNodesToMoveOrMechanicsBlock(
    editor,
    createTrackCompletionNode(
      stripMarkdown(plugin, trackContext.name),
      trackContext.location
    )
  );
}
async function markTrackIncomplete(plugin, editor, view) {
  const actionContext = await determineCharacterActionContext(plugin, view);
  const progressContext = new ProgressContext(plugin, actionContext);
  const trackContext = await selectProgressTrack(
    progressContext,
    plugin,
    ({ trackType, track }) => trackType !== "Legacy" && track.complete
  );
  await trackContext.process((trackAdapter) => trackAdapter.markIncomplete());
  appendNodesToMoveOrMechanicsBlock(
    editor,
    createTrackIncompletionNode(
      stripMarkdown(plugin, trackContext.name),
      trackContext.location
    )
  );
}

// src/utils/ui/generic-fuzzy-suggester.ts
var import_obsidian62 = require("obsidian");
var GenericFuzzySuggester = class extends import_obsidian62.FuzzySuggestModal {
  data = [];
  callbackFunction;
  constructor(plugin) {
    super(plugin.app);
    this.scope.register(["Shift"], "Enter", (evt) => {
      this.enterTrigger(evt);
    });
    this.scope.register(["Ctrl"], "Enter", (evt) => {
      this.enterTrigger(evt);
    });
  }
  setSuggesterData(suggesterData) {
    this.data = suggesterData;
  }
  display(callBack) {
    this.callbackFunction = callBack;
    this.open();
  }
  getItems() {
    return this.data;
  }
  getItemText(item) {
    return item.display;
  }
  onChooseItem() {
    return;
  }
  renderSuggestion(item, el) {
    el.createEl("div", { text: item.item.display });
  }
  enterTrigger(evt) {
    const selectedText = document.querySelector(
      ".suggestion-item.is-selected div"
    )?.textContent;
    const item = this.data.find((i7) => i7.display === selectedText);
    if (item) {
      this.invokeCallback(item, evt);
      this.close();
    }
  }
  onChooseSuggestion(item, evt) {
    this.invokeCallback(item.item, evt);
  }
  invokeCallback(item, evt) {
    if (typeof this.callbackFunction === "function") {
      this.callbackFunction(item, evt);
    }
  }
};

// src/characters/meter-commands.ts
async function burnMomentum(plugin, editor, view) {
  const actionContext = await requireActiveCharacterContext(plugin, view);
  const [path, charContext] = [
    actionContext.characterPath,
    actionContext.characterContext
  ];
  const { lens, character } = charContext;
  const oldValue = lens.momentum.get(character);
  if (oldValue > 0) {
    const updated = await charContext.updater(
      vaultProcess(plugin.app, path),
      (character2, { lens: lens2 }) => {
        return momentumOps(lens2).reset(character2);
      }
    );
    const newValue = lens.momentum.get(updated);
    const burnNode = node("burn", {
      properties: { from: oldValue, to: newValue }
    });
    appendNodesToMoveOrMechanicsBlockWithActor(
      editor,
      plugin,
      actionContext,
      burnNode
    );
  }
}
async function promptForMeter(app, actionContext, meterFilter) {
  const { value: meter } = await CustomSuggestModal.selectWithUserEntry(
    app,
    actionContext.conditionMeters.filter(meterFilter),
    labelForMeter,
    (input, el) => {
      el.setText(`Use custom meter '${input}'`);
    },
    (match, el) => {
      el.createEl("small", { text: `${match.item.value}` });
    },
    "Choose a meter",
    (input) => ({
      key: input,
      lens: void 0,
      value: void 0,
      definition: {
        kind: "condition_meter",
        label: input,
        min: -10,
        max: 10,
        rollable: true
      }
    })
  );
  return meter;
}
var modifyMeterCommand = async (plugin, editor, view, verb, meterFilter, allowableValues) => {
  const actionContext = await determineCharacterActionContext(plugin, view);
  const choice = await promptForMeter(plugin.app, actionContext, meterFilter);
  let measure;
  if (choice.value == null) {
    const value = await CustomSuggestModal.select(
      plugin.app,
      numberRange(choice.definition.min, choice.definition.max),
      (n6) => n6.toString(10),
      void 0,
      `What is the starting value of ${choice.definition.label}?`
    );
    measure = { ...choice, value };
  } else {
    measure = choice;
  }
  const modifier = await CustomSuggestModal.select(
    plugin.app,
    allowableValues(measure),
    (n6) => n6.toString(),
    void 0,
    `Choose the amount to ${verb} on the '${measure.definition.label}' meter.`
  );
  let newValue;
  if (actionContext instanceof CharacterActionContext && measure.lens) {
    const updated = await actionContext.update(
      plugin.app,
      updating(measure.lens, (startVal) => startVal + modifier)
    );
    newValue = measure.lens.get(updated);
  } else {
    newValue = measure.value + modifier;
  }
  const meterNode = node("meter", {
    values: [labelForMeter(measure)],
    properties: { from: measure.value, to: newValue }
  });
  appendNodesToMoveOrMechanicsBlockWithActor(
    editor,
    plugin,
    actionContext,
    meterNode
  );
};

